import{_ as n,o as t,c as a,a2 as r}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"Mit einer Vorlage starten","description":"Einen Space aus einer fertigen Vorlage anlegen.","frontmatter":{"title":"Mit einer Vorlage starten","description":"Einen Space aus einer fertigen Vorlage anlegen."},"headers":[],"relativePath":"erste-schritte/vorlagen.md","filePath":"erste-schritte/vorlagen.md","lastUpdated":1786093505000}'),i={name:"erste-schritte/vorlagen.md"};function s(l,e,o,d,h,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="mit-einer-vorlage-starten" tabindex="-1">Mit einer Vorlage starten <a class="header-anchor" href="#mit-einer-vorlage-starten" aria-label="Permalink to &quot;Mit einer Vorlage starten&quot;">​</a></h1><p>Unter der Space-Übersicht steht <em>Oder starten Sie mit einem Template</em>. Eine Vorlage legt einen fertigen Space an — mit Grids, Ansichten und je nach Vorlage auch Formularen, Flows und Seiten.</p><h2 id="warum-eine-vorlage" tabindex="-1">Warum eine Vorlage <a class="header-anchor" href="#warum-eine-vorlage" aria-label="Permalink to &quot;Warum eine Vorlage&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Auch als Lernmittel nützlich</p><p>Eine Vorlage zeigt, wie ein durchdachter Aufbau aussieht: wie Grids verknüpft sind, welche Ansichten sinnvoll sind, wie ein Flow aufgebaut wird.</p><p>Selbst wenn Sie am Ende etwas Eigenes bauen, lohnt es sich, eine passende Vorlage einmal anzulegen und auseinanderzunehmen. Das geht schneller als jede Anleitung.</p></div><h2 id="vorlage-verwenden" tabindex="-1">Vorlage verwenden <a class="header-anchor" href="#vorlage-verwenden" aria-label="Permalink to &quot;Vorlage verwenden&quot;">​</a></h2><ol><li>Öffnen Sie die Space-Übersicht.</li><li>Wählen Sie unter <em>Oder starten Sie mit einem Template</em> eine Vorlage aus.</li><li>Folgen Sie der Anlage.</li></ol><p>Es entsteht ein <strong>neuer Space</strong>. Bestehende Spaces bleiben unberührt.</p><h2 id="tarifbindung" tabindex="-1">Tarifbindung <a class="header-anchor" href="#tarifbindung" aria-label="Permalink to &quot;Tarifbindung&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Manche Vorlagen brauchen einen höheren Tarif</p><blockquote><p><em>Für dieses Template benötigen Sie mindestens einen „{plan}&quot; Plan</em></p></blockquote><p>Das liegt daran, dass Vorlagen Funktionen nutzen können, die tarifgebunden sind — mehrere Flows, Pro-Schritte, erweiterte Formulareinstellungen.</p></div><div class="danger custom-block"><p class="custom-block-title">Nach der Testphase kann eine Vorlage unbenutzbar werden</p><blockquote><p><strong>Testphase abgeschlossen</strong></p><p><em>Sie haben die Testphase für dieses Template abgeschlossen. Um dieses Template weiterhin nutzen zu können, upgraden Sie bitte auf einen höheren Plan.</em></p></blockquote><p>Prüfen Sie deshalb <strong>vor</strong> dem produktiven Einsatz, welchen Tarif eine Vorlage voraussetzt — und ob Sie ihn nach der Testphase buchen wollen.</p><p>Die verbleibenden Testtage stehen in den <a href="/docs/spaces/einstellungen">Space-Einstellungen</a>.</p></div><h2 id="nach-dem-anlegen" tabindex="-1">Nach dem Anlegen <a class="header-anchor" href="#nach-dem-anlegen" aria-label="Permalink to &quot;Nach dem Anlegen&quot;">​</a></h2><p>Eine Vorlage ist ein Ausgangspunkt, kein fertiges Produkt. Üblicherweise passen Sie an:</p><table tabindex="0"><thead><tr><th>Bereich</th><th>Typische Anpassung</th></tr></thead><tbody><tr><td><strong>Felder</strong></td><td>Eigene Felder ergänzen, nicht benötigte entfernen</td></tr><tr><td><strong>Auswahloptionen</strong></td><td>An die eigene Terminologie anpassen</td></tr><tr><td><strong>Formulare</strong></td><td>Texte, Farben, Logo</td></tr><tr><td><strong>Flows</strong></td><td>E-Mail-Texte und Empfänger prüfen</td></tr><tr><td><strong>Ansichten</strong></td><td>Filter an die eigene Arbeitsweise anpassen</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Flows aus Vorlagen vor dem Einsatz prüfen</p><p>Eine Vorlage kann Flows enthalten, die E-Mails verschicken. Gehen Sie diese durch, <strong>bevor</strong> Sie das erste Formular teilen:</p><ul><li>An wen geht die E-Mail? Steht dort noch eine Beispieladresse?</li><li>Passt der Text?</li><li>Welcher Auslöser ist gesetzt?</li></ul><p>Sehen Sie sich dazu die <a href="/docs/flows/was-ist-ein-flow">Flow-Liste</a> des neuen Space an.</p></div><div class="tip custom-block"><p class="custom-block-title">Externe Links kontrollieren</p><p>Prüfen Sie außerdem die <a href="/docs/zusammenarbeit/externe-links">Links-Übersicht</a> des Space. Enthält die Vorlage bereits veröffentlichte Formulare oder Portale, sind diese möglicherweise sofort erreichbar.</p></div><h2 id="vorlage-oder-selbst-bauen" tabindex="-1">Vorlage oder selbst bauen? <a class="header-anchor" href="#vorlage-oder-selbst-bauen" aria-label="Permalink to &quot;Vorlage oder selbst bauen?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Empfehlung</th></tr></thead><tbody><tr><td>Der Anwendungsfall passt gut zu einer Vorlage</td><td><strong>Vorlage</strong></td></tr><tr><td>Sie wollen ApptiveGrid kennenlernen</td><td><strong>Vorlage</strong> — dann auseinandernehmen</td></tr><tr><td>Sie haben genaue eigene Vorstellungen</td><td><strong>Selbst bauen</strong></td></tr><tr><td>Die Vorlage braucht einen Tarif, den Sie nicht wollen</td><td><strong>Selbst bauen</strong></td></tr><tr><td>Sie brauchen nur ein einfaches Formular</td><td><strong>Selbst bauen</strong> — schneller als jede Vorlage</td></tr></tbody></table><p>→ <a href="/docs/erste-schritte/schnellstart">In 15 Minuten zur ersten Anwendung</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/spaces/space-anlegen">Space anlegen</a></li><li><a href="/docs/erste-schritte/schnellstart">In 15 Minuten zur ersten Anwendung</a></li><li><a href="/docs/zusammenarbeit/externe-links">Externe Links im Überblick</a> — Vorlagen können bereits Links enthalten</li></ul>',20)])])}const p=n(i,[["render",s]]);export{u as __pageData,p as default};
